#!/usr/bin/env python3
"""Run from project root: python3 fix_vercel_cron.py"""
import base64, os, sys

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "vercel.json": "",
    "app/api/cron/bags-sync/route.ts": "",
    ".github/workflows/ci.yml": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print(f"WRITTEN  {path}")

print("""
Done. Now:
  git add vercel.json .github/workflows/ci.yml app/api/cron/bags-sync/route.ts
  git commit -m "fix: vercel.json daily cron only, remove 6-hourly blocker"
  git push origin main
  
Then in Vercel dashboard:
  Settings -> Git -> check 'Auto Deploy' is ON for branch 'main'
  Deployments -> trigger one manual deploy to clear any blocked state
""")
